import{_ as e}from"./chunks/img.Dck1PxLc.js";import{_ as t,c as a,o,a0 as i}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"About Pétanque Academy","description":"","frontmatter":{},"headers":[],"relativePath":"en/about.md","filePath":"en/about.md"}');const n=t({name:"en/about.md"},[["render",function(t,r,n,s,l,h){return o(),a("div",null,[...r[0]||(r[0]=[i('<h1 id="about-petanque-academy" tabindex="-1">About Pétanque Academy <a class="header-anchor" href="#about-petanque-academy" aria-label="Permalink to &quot;About Pétanque Academy&quot;">​</a></h1><h2 id="a-passion-for-petanque" tabindex="-1">A Passion for Pétanque <a class="header-anchor" href="#a-passion-for-petanque" aria-label="Permalink to &quot;A Passion for Pétanque&quot;">​</a></h2><p>Welcome to Pétanque Academy, where a deep-seated passion for pétanque has been a driving force for over 45 years. My journey with this sport has been one of dedication, skill, and continuous enthusiasm.</p><p>Pétanque isn&#39;t just a game; it&#39;s a way to connect, strategize, and enjoy the outdoors, and I&#39;ve been fortunate to experience its many facets for nearly half a century. Whether it&#39;s the precise placement of a boule or the camaraderie on the terrain, my commitment to pétanque remains as strong as ever.</p><p><img src="'+e+'" alt="Patrik Wiik with friends"></p><p><em>Sharing this passion with friends is truly what makes pétanque so special. The countless hours spent on the terrain, filled with laughter, friendly competition, and shared stories, build bonds that last a lifetime.</em></p><hr><h2 id="my-mission" tabindex="-1">My Mission <a class="header-anchor" href="#my-mission" aria-label="Permalink to &quot;My Mission&quot;">​</a></h2><p>The mission of Pétanque Academy is to help elite players unlock their full potential by addressing the mental game - the often-overlooked aspect that separates good players from great ones.</p><p>Through this site, I share:</p><ul><li><strong>Mental game frameworks</strong> developed from decades of experience</li><li><strong>Practical tools and templates</strong> for goal setting and training</li><li><strong>Workshop methodologies</strong> for building psychological safety</li><li><strong>Evidence-based approaches</strong> to performance under pressure</li></ul><p>This isn&#39;t about technical coaching - it&#39;s about creating the mental foundation that allows your technical skills to shine when it matters most.</p><hr><h2 id="why-i-created-this-site" tabindex="-1">Why I Created This Site <a class="header-anchor" href="#why-i-created-this-site" aria-label="Permalink to &quot;Why I Created This Site&quot;">​</a></h2><p>After 45+ years in pétanque, I&#39;ve seen countless talented players struggle not with technique, but with:</p><ul><li><strong>Inner critic</strong> that destroys confidence after mistakes</li><li><strong>Pressure</strong> that makes them play differently in competition</li><li><strong>Lack of structure</strong> in mental training</li><li><strong>Isolation</strong> in their development journey</li></ul><p>This site exists to change that. Every piece of content here is designed to be immediately practical - templates you can copy, frameworks you can apply today, and tools that work in real competition.</p><hr><h2 id="get-in-touch" tabindex="-1">Get in Touch <a class="header-anchor" href="#get-in-touch" aria-label="Permalink to &quot;Get in Touch&quot;">​</a></h2><p>I&#39;d love to hear from you! Whether you have questions, want to share your experience, or are interested in workshops and training, feel free to reach out.</p><h3 id="contact-information" tabindex="-1">Contact Information <a class="header-anchor" href="#contact-information" aria-label="Permalink to &quot;Contact Information&quot;">​</a></h3><p><strong>Email:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="help-me-improve-this-site" tabindex="-1">Help Me Improve This Site <a class="header-anchor" href="#help-me-improve-this-site" aria-label="Permalink to &quot;Help Me Improve This Site&quot;">​</a></h2><p>Your feedback is invaluable! This site is constantly evolving based on what elite players actually need.</p><h3 id="i-d-love-to-hear-from-you-about" tabindex="-1">I&#39;d Love to Hear From You About: <a class="header-anchor" href="#i-d-love-to-hear-from-you-about" aria-label="Permalink to &quot;I&#39;d Love to Hear From You About:&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">What Would Help You Most?</p><ul><li><p><strong>What content would you like to see more of?</strong></p><ul><li>More mental game techniques?</li><li>More practical templates?</li><li>Case studies from elite players?</li></ul></li><li><p><strong>What&#39;s missing from the site?</strong></p><ul><li>Topics not covered?</li><li>Tools you wish existed?</li><li>Resources you can&#39;t find?</li></ul></li><li><p><strong>What&#39;s working well?</strong></p><ul><li>Which pages have been most helpful?</li><li>Which tools have you actually used?</li><li>What made the biggest difference for you?</li></ul></li><li><p><strong>How can I make it better?</strong></p><ul><li>Navigation improvements?</li><li>Content organization?</li><li>More examples?</li><li>Different formats?</li></ul></li></ul></div><h3 id="send-me-your-feedback" tabindex="-1">Send Me Your Feedback <a class="header-anchor" href="#send-me-your-feedback" aria-label="Permalink to &quot;Send Me Your Feedback&quot;">​</a></h3><p><strong>Email your thoughts to:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Subject line suggestions:</strong></p><ul><li>&quot;Site Feedback: [Your Topic]&quot;</li><li>&quot;Content Request: [What You Need]&quot;</li><li>&quot;Success Story: [How It Helped]&quot;</li><li>&quot;Suggestion: [Your Idea]&quot;</li></ul><p><strong>What to include:</strong></p><ul><li>Your current level/experience</li><li>What you&#39;re working on</li><li>Specific feedback or requests</li><li>Any success stories using the content</li></ul><hr><h2 id="what-others-are-saying" tabindex="-1">What Others Are Saying <a class="header-anchor" href="#what-others-are-saying" aria-label="Permalink to &quot;What Others Are Saying&quot;">​</a></h2><details class="details custom-block"><summary>Feedback from Elite Players</summary><p><em>&quot;The mental game content has completely changed how I approach competition. The Inner Coach framework alone was worth finding this site.&quot;</em><br> — Regional Champion, France</p><p><em>&quot;Finally, someone who understands that technique isn&#39;t the problem. The workshop methodology gave our club a whole new way to train.&quot;</em><br> — National Team Player, Sweden</p><p><em>&quot;The goal template and diary template are exactly what I needed. Simple, practical, and actually usable.&quot;</em><br> — Tournament Player, Spain</p></details><hr><h2 id="about-the-content" tabindex="-1">About the Content <a class="header-anchor" href="#about-the-content" aria-label="Permalink to &quot;About the Content&quot;">​</a></h2><p>All content on this site is:</p><ul><li><strong>Free and accessible</strong> - No paywalls, no hidden content</li><li><strong>Practical and actionable</strong> - Templates you can use today</li><li><strong>Evidence-based</strong> - Built on psychology research and 45+ years of experience</li><li><strong>Continuously updated</strong> - New content added based on your feedback</li></ul><hr><h2 id="privacy-cookies" tabindex="-1">Privacy &amp; Cookies <a class="header-anchor" href="#privacy-cookies" aria-label="Permalink to &quot;Privacy &amp; Cookies&quot;">​</a></h2><p>This site uses Google AdSense to help support its operation. By using this site, you agree to Google&#39;s use of cookies for ad personalization and analytics.</p><p><strong>We respect your privacy:</strong></p><ul><li>No personal data is collected beyond standard analytics</li><li>No email lists or spam</li><li>Contact information is only used to respond to your messages</li></ul><hr><h2 id="connect-share" tabindex="-1">Connect &amp; Share <a class="header-anchor" href="#connect-share" aria-label="Permalink to &quot;Connect &amp; Share&quot;">​</a></h2><p>If you find this content valuable:</p><ul><li><strong>Share it</strong> with your training partners</li><li><strong>Recommend it</strong> to your club</li><li><strong>Link to it</strong> from your own resources</li><li><strong>Give feedback</strong> to help it improve</li></ul><p>Together, we can elevate the mental game of pétanque worldwide.</p><hr><p><strong>Thank you for being part of Pétanque Academy!</strong></p><p><em>— Patrik Wiik</em></p>',54)])])}]]);export{r as __pageData,n as default};
